def is_prime(n: int) -> bool:
    """Return whether n is prime."""
    # Handle edge cases
    if n < 2:
        return False
    if n in (2, 3):
        return True
    # Even numbers greater than 2 are not prime
    if n % 2 == 0:
        return False

    # Trial division up to sqrt(n). For moderate sized inputs this is fine.
    # We check odd divisors only.
    limit = int(n**0.5) + 1
    for d in range(3, limit, 2):
        if n % d == 0:
            return False
    return True
EOF

